use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut sorted_ids = Vec::new();
    for pair in input.as_array() {
        let priority = pair[0].as_i64().unwrap();
        let id = pair[1].as_i64().unwrap();
        sorted_ids.push((priority, id));
    }

    sorted_ids.sort_by(|a, b| b.0.cmp(&a.0));
    sorted_ids.into_iter().map(|(priority, id)| serde_json::Value::Number(id)).collect()
}

fn main() {
    let input = serde_json::Value::from("{\"input\":[[2,7],[3,8],[2,1]],\"expected\":[8,1,7]}");
    let result = solve(input);
    println!("{:?}", result);
}
```

